import{_ as l,a0 as t,w as o,s as r,ao as d,I as i,x as a,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"在 Linux 中遨游手册页的海洋 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中遨游手册页的海洋 | LCTT (202004) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中遨游手册页的海洋 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中遨游手册页的海洋 | LCTT (202004) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202004/20200211 Navigating man pages in Linux","title":"在 Linux 中遨游手册页的海洋","tag":"202004","desc":""},"relativePath":"202004/20200211 Navigating man pages in Linux.md","filePath":"[post].md"}'),c={name:"202004/20200211 Navigating man pages in Linux.md"};function u(h,s,g,m,k,b){const n=t("Link");return o(),r("div",null,[s[15]||(s[15]=d(`<h1 id="在-linux-中遨游手册页的海洋" tabindex="-1">在 Linux 中遨游手册页的海洋 <a class="header-anchor" href="#在-linux-中遨游手册页的海洋" aria-label="Permalink to “在 Linux 中遨游手册页的海洋”">​</a></h1><blockquote><p>Linux 系统上的手册页可以做的不仅仅是提供特定命令的信息。它们可以帮助你发现你没有意识到的命令。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/10/field-note_play-book_playbook_map_navigation_journey_by-hello-i-m-nik-via-unsplash-100813507-large.jpg" alt="Hello I&#39;m Nik"></p><p>手册页提供了关于 Linux 命令的基本信息，很多用户经常参考它，但手册页的内容比我们很多人意识到的要多得多。</p><p>你总是可以输入一个像 <code>man who</code> 这样的命令，然后得到 <code>who</code> 命令的工作原理的漂亮描述，但是探索你可能不知道的命令可能会更有启发。例如，你可以使用 <code>man</code> 命令来帮助找到一些处理非常具有挑战性的任务的命令，或者显示一些选项，这些选项可以帮助你以新的更好的方式使用你已经知道的命令。</p><p>让我们来浏览一些选项，看看最终的结果是什么。</p><h3 id="用-man-去识别命令" tabindex="-1">用 man 去识别命令 <a class="header-anchor" href="#用-man-去识别命令" aria-label="Permalink to “用 man 去识别命令”">​</a></h3><p><code>man</code> 命令可以帮助你按主题查找命令。例如，如果你要找一个计算文件中的行数的命令，你可以提供一个关键字。在下面的例子中，我们把关键字 “count” 放在了引号中，并添加了空格，这样我们就不会得到与 “accounts” 或 “accounting” 相关的命令，而是得到那些可以为我们做一些计算的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man -k &#39; count &#39;</span></span>
<span class="line"><span>anvil (8postfix)     - Postfix session count and request rate control</span></span>
<span class="line"><span>cksum (1)            - checksum and count the bytes in a file</span></span>
<span class="line"><span>sum (1)              - checksum and count the blocks in a file</span></span>
<span class="line"><span>timer_getoverrun (2) - get overrun count for a POSIX per-process timer</span></span></code></pre></div><p>为了显示与新用户账户相关的命令，我们可以尝试使用这样的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man -k &quot;new user&quot;</span></span>
<span class="line"><span>newusers (8)         - update and create new users in batch</span></span>
<span class="line"><span>useradd (8)          - create a new user or update default new user information</span></span>
<span class="line"><span>zshroadmap (1)       - informal introduction to the zsh manual The Zsh Manual, …</span></span></code></pre></div><p>需要说明的是，上面的第三项只是提到 “new users” 类似的内容，并不是设置、删除或配置用户账号的命令。<code>man</code> 命令只是在命令描述中匹配了一些词，作用很像 <code>apropos</code> 命令。注意上面列出的每个命令后面的括号中的数字。这些数字与包含这些命令的手册页的分区有关。</p><h3 id="确定手册页的分区" tabindex="-1">确定手册页的分区 <a class="header-anchor" href="#确定手册页的分区" aria-label="Permalink to “确定手册页的分区”">​</a></h3><p><code>man</code> 命令的分区将其内容划分为不同的类别。要列出这些类别，请键入 <code>man man</code>，并查看类似下面的描述。你的系统中很可能没有第 9 分区的命令。</p><ul><li><code>1</code>：可执行程序或 shell 命令</li><li><code>2</code>：系统调用（内核提供的函数）</li><li><code>3</code>：库调用（程序库内的函数）</li><li><code>4</code>：特殊文件（通常在可以 <code>/dev</code> 中找到）</li><li><code>5</code>：文件格式和惯例，例如 <code>/etc/passwd</code></li><li><code>6</code>：游戏</li><li><code>7</code>：杂项（包括宏包和约定），例如 <code>man</code>(7)、<code>groff</code>(7)</li><li><code>8</code>：系统管理命令（通常只由 root 用户使用）</li><li><code>9</code>：内核例程（非标准）</li></ul><p>手册页涵盖了比我们通常认为的“命令”更多的内容。从上面的描述中可以看到，它们涵盖了系统调用、库调用、特殊文件等等。</p><p>下面的列表显示了 Linux 系统中的手册页的实际存储位置。这些目录上的日期会有所不同，因为随着更新，其中一些分区会有新的内容，而另一些则不会。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -ld /usr/share/man/man?</span></span>
<span class="line"><span>drwxr-xr-x 2 root root  98304 Feb  5 16:27 /usr/share/man/man1</span></span>
<span class="line"><span>drwxr-xr-x 2 root root  65536 Oct 23 17:39 /usr/share/man/man2</span></span>
<span class="line"><span>drwxr-xr-x 2 root root 270336 Nov 15 06:28 /usr/share/man/man3</span></span>
<span class="line"><span>drwxr-xr-x 2 root root   4096 Feb  4 10:16 /usr/share/man/man4</span></span>
<span class="line"><span>drwxr-xr-x 2 root root  28672 Feb  5 16:25 /usr/share/man/man5</span></span>
<span class="line"><span>drwxr-xr-x 2 root root   4096 Oct 23 17:40 /usr/share/man/man6</span></span>
<span class="line"><span>drwxr-xr-x 2 root root  20480 Feb  5 16:25 /usr/share/man/man7</span></span>
<span class="line"><span>drwxr-xr-x 2 root root  57344 Feb  5 16:25 /usr/share/man/man8</span></span></code></pre></div><p>注意，为了节省空间，手册页文件一般都是 gzip 压缩的。每当你使用 <code>man</code> 命令时，<code>man</code> 命令会根据需要解压。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /usr/share/man/man1 | head -10</span></span>
<span class="line"><span>total 12632</span></span>
<span class="line"><span>lrwxrwxrwx 1 root root      9 Sep  5 06:38 [.1.gz -&gt; test.1.gz</span></span>
<span class="line"><span>-rw-r--r-- 1 root root    563 Nov  7 05:07 2to3-2.7.1.gz</span></span>
<span class="line"><span>-rw-r--r-- 1 root root    592 Apr 23  2016 411toppm.1.gz</span></span>
<span class="line"><span>-rw-r--r-- 1 root root   2866 Aug 14 10:36 a2query.1.gz</span></span>
<span class="line"><span>-rw-r--r-- 1 root root   2361 Sep  9 15:13 aa-enabled.1.gz</span></span>
<span class="line"><span>-rw-r--r-- 1 root root   2675 Sep  9 15:13 aa-exec.1.gz</span></span>
<span class="line"><span>-rw-r--r-- 1 root root   1142 Apr  3  2018 aaflip.1.gz</span></span>
<span class="line"><span>-rw-r--r-- 1 root root   3847 Aug 14 10:36 ab.1.gz</span></span>
<span class="line"><span>-rw-r--r-- 1 root root   2378 Aug 23  2018 ac.1.gz</span></span></code></pre></div><h3 id="按分区列出的手册页" tabindex="-1">按分区列出的手册页 <a class="header-anchor" href="#按分区列出的手册页" aria-label="Permalink to “按分区列出的手册页”">​</a></h3><p>即使只看第 1 分区的前 10 个手册页（如上所示），你也可能会看到一些新的命令 —— 也许是 <code>a2query</code> 或 <code>aaflip</code>（如上所示）。</p><p>探索命令的更好策略是按分区列出命令，不查看文件本身，而是使用 <code>man</code> 命令向你显示命令并提供每个命令的简要说明。</p><p>在下面的命令中，<code>-s 1</code> 指示 <code>man</code> 显示第 1 分区中的命令信息。<code>-k .</code> 使该命令对所有命令都有效，而不是指定一个特定的关键字；如果没有这个，<code>man</code> 命令就会回过头来问：“你想要什么手册页？”所以，使用关键字来选择一组相关的命令，或者使用点来显示一个分区中的所有命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man -s 1 -k .</span></span>
<span class="line"><span>2to3-2.7 (1)         - Python2 to Python3 converter</span></span>
<span class="line"><span>411toppm (1)         - convert Sony Mavica .411 image to ppm</span></span>
<span class="line"><span>as (1)               - the portable GNU assembler.</span></span>
<span class="line"><span>baobab (1)           - A graphical tool to analyze disk usage</span></span>
<span class="line"><span>busybox (1)          - The Swiss Army Knife of Embedded Linux</span></span>
<span class="line"><span>cmatrix (1)          - simulates the display from &quot;The Matrix&quot;</span></span>
<span class="line"><span>expect_dislocate (1) - disconnect and reconnect processes</span></span>
<span class="line"><span>red (1)              - line-oriented text editor</span></span>
<span class="line"><span>enchant (1)          - a spellchecker</span></span>
<span class="line"><span>…</span></span></code></pre></div><h3 id="有多少手册页" tabindex="-1">有多少手册页？ <a class="header-anchor" href="#有多少手册页" aria-label="Permalink to “有多少手册页？”">​</a></h3><p>如果你对每个分区中有多少手册页感到好奇，可以使用以下命令按分区对它们进行计数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ for num in {1..8}</span></span>
<span class="line"><span>&gt; do</span></span>
<span class="line"><span>&gt;   man -s $num -k . | wc -l</span></span>
<span class="line"><span>&gt; done</span></span>
<span class="line"><span>2382</span></span>
<span class="line"><span>493</span></span>
<span class="line"><span>2935</span></span>
<span class="line"><span>53</span></span>
<span class="line"><span>441</span></span>
<span class="line"><span>11</span></span>
<span class="line"><span>245</span></span>
<span class="line"><span>919</span></span></code></pre></div><p>确切的数量可能有所不同，但是大多数 Linux 系统的命令数量差不多。如果我们使用命令将这些数字加在一起，我们可以看到运行该命令的系统上有将近 7500 个手册页。有很多命令，系统调用等。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ for num in {1..8}</span></span>
<span class="line"><span>&gt; do</span></span>
<span class="line"><span>&gt;     num=\`man -s $num -k . | wc -l\`</span></span>
<span class="line"><span>&gt;     tot=\`expr $num + $tot\`</span></span>
<span class="line"><span>&gt;     echo $tot</span></span>
<span class="line"><span>&gt; done</span></span>
<span class="line"><span>2382</span></span>
<span class="line"><span>2875</span></span>
<span class="line"><span>5810</span></span>
<span class="line"><span>5863</span></span>
<span class="line"><span>6304</span></span>
<span class="line"><span>6315</span></span>
<span class="line"><span>6560</span></span>
<span class="line"><span>7479            &lt;=== total</span></span></code></pre></div><p>阅读手册页可以学到很多东西，但是以其他方式浏览手册页可以帮助你了解系统上可能不知道的命令。</p><hr>`,32)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3519853/navigating-man-pages-in-linux.html"},{default:p(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3519853/navigating-man-pages-in-linux.html",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:p(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const y=l(c,[["render",u]]);export{w as __pageData,y as default};
